  FROM cross_reference_threads t
  JOIN _s314_chr2_03_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='2-chronicles' AND sv.chapter_number=3 AND sv.verse_number=1
  JOIN _s314_chr2_03_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='genesis' AND tv.chapter_number=22 AND tv.verse_number=2
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='2-chronicles-3-the-house-of-yahuah-on-mount-moriah-the-place-of-the-offering'
