INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 4, E'*within the oracle he made two cherubims of olive tree* (1 Kings 6:23) — the parallel account of the same two cherubim of the oracle.'
  FROM cross_reference_threads t
