INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 3, E'*We have an altar, whereof they have no right to eat which serve the tabernacle* (Hebrews 13:10) — the altar of sacrifice fulfilled in the Messiah, who *suffered without the gate* (Hebrews 13:12).'
  FROM cross_reference_threads t
