-- THREAD 2: the molten sea + lavers
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'*Thou shalt also make a laver of brass... to wash withal... between the tabernacle of the congregation and the altar* (Exodus 30:18) — the single wilderness laver Solomon multiplies into the sea and ten lavers.'
  FROM cross_reference_threads t
  JOIN _s314_chr2_04_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='2-chronicles' AND sv.chapter_number=4 AND sv.verse_number=6
  JOIN _s314_chr2_04_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='exodus' AND tv.chapter_number=30 AND tv.verse_number=18
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='2-chronicles-4-the-molten-sea-the-washing-to-approach-the-holy'
