INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 2, E'*they shall wash with water, that they die not... when they come near to the altar to minister* (Exodus 30:20) — the washing was a matter of life: none approaches the holy unwashed.'
  FROM cross_reference_threads t
