-- THREAD 1
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'*Moses drew near unto the thick darkness where Elohim (God) was.* (Exodus 20:21) — the Sinai darkness Solomon''s house is built to receive.'
  FROM cross_reference_threads t
  JOIN _s314_chr2_06_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='2-chronicles' AND sv.chapter_number=6 AND sv.verse_number=1
  JOIN _s314_chr2_06_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='exodus' AND tv.chapter_number=20 AND tv.verse_number=21
