INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 11, E'*Let no man therefore judge you... of an holyday, or of the new moon, or of the sabbath days* (Colossians 2:16) — the same triad named in the apostolic age, a shadow whose body is the Messiah''s.'
  FROM cross_reference_threads t
  JOIN _s314_chr2_08_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='2-chronicles' AND sv.chapter_number=8 AND sv.verse_number=13
  JOIN _s314_chr2_08_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='colossians' AND tv.chapter_number=2 AND tv.verse_number=16
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='2-chronicles-8-the-appointed-times-kept-the-sabbaths-new-moons-and-the-three-feasts'
