SELECT t.id, cr.id, 2, E'*if ye seek him, he will be found of you; but if ye forsake him, he will forsake you* (2 Chronicles 15:2) — Azariah''s covenant terms that Hanani now enforces.'
  FROM cross_reference_threads t
  JOIN _s314_chr2_16_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='2-chronicles' AND sv.chapter_number=16 AND sv.verse_number=7
  JOIN _s314_chr2_16_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='2-chronicles' AND tv.chapter_number=15 AND tv.verse_number=2
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='2-chronicles-16-asa-hires-syria-the-arm-of-flesh-not-yahuah'
