INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'*I will lift up mine eyes unto the hills, from whence cometh my help* (Psalm 121:1) — the lifted-eye posture of Jehoshaphat''s *our eyes are upon thee* (2 Chronicles 20:12).'
  FROM cross_reference_threads t
  JOIN _s314_chr2_20_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='2-chronicles' AND sv.chapter_number=20 AND sv.verse_number=12
  JOIN _s314_chr2_20_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='psalms' AND tv.chapter_number=121 AND tv.verse_number=1
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='2-chronicles-20-our-eyes-are-upon-thee-the-prayer-of-utter-dependence'
ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;

