SELECT t.id, cr.id, 4, E'*Mine eyes are ever toward Yahuah (LORD); for he shall pluck my feet out of the net* (Psalm 25:15) — the fixed gaze that brings the foot out of the enemy''s net (2 Chronicles 20:12).'
  FROM cross_reference_threads t
