INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 6, E'*that we should not trust in ourselves, but in Elohim (God) which raiseth the dead* (2 Corinthians 1:9) — Paul names the lesson Jehoshaphat lived: the end of self-might is trust in Yahuah (2 Chronicles 20:12).'
  FROM cross_reference_threads t
