-- Thread 2
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'*I desired mercy, and not sacrifice* (Hosea 6:6) — the heart of Yahuah that Oded presses on the north (28:9).'
  FROM cross_reference_threads t
