INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 2, E'*The tithes... I have given to the Levites to inherit* (Numbers 18:24) — the portion Hezekiah restores *that they might be encouraged in the law*.'
  FROM cross_reference_threads t
