INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 3, E'*All the tithe of the land... is the LORD''S: it is holy unto Yahuah (LORD)* (Leviticus 27:30) — the tenth was always set apart, never the people''s to keep back.'
  FROM cross_reference_threads t
  JOIN _s314_chr2_31_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='2-chronicles' AND sv.chapter_number=31 AND sv.verse_number=5
  JOIN _s314_chr2_31_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='leviticus' AND tv.chapter_number=27 AND tv.verse_number=30
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='2-chronicles-31-the-tithe-the-portion-of-the-ministry-per-the-torah'
