-- THREAD 1 members
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'*the whole assembly... shall kill it in the evening* (Exodus 12:6) — the fourteenth-day passover Yahuah ordained in Egypt, kept by Josiah to the day.'
  FROM cross_reference_threads t
  JOIN _s314_chr2_35_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='2-chronicles' AND sv.chapter_number=35 AND sv.verse_number=1
  JOIN _s314_chr2_35_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='exodus' AND tv.chapter_number=12 AND tv.verse_number=6
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='2-chronicles-35-josiah-kept-the-passover-as-it-is-written-in-the-book-of-moses'
