INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 2, E'*In the fourteenth day of the first month at even is the LORD''S passover* (Leviticus 23:5) — the appointed time in the calendar of the feasts.'
