INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 4, E'*in the place which Yahuah (LORD) shall choose to place his name there* (Deuteronomy 16:2) — the feast gathered to Jerusalem, the chosen place.'
