-- THREAD 1
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 1, E'*I have even sent unto you all my servants the prophets, daily rising up early* (Jeremiah 7:25) — the same patient sending behind 36:15.'
  FROM cross_reference_threads t
  JOIN _s314_chr2_36_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='2-chronicles' AND sv.chapter_number=36 AND sv.verse_number=15
  JOIN _s314_chr2_36_lookup tv ON tv.edition_slug='canon' AND tv.book_slug='jeremiah' AND tv.chapter_number=7 AND tv.verse_number=25
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='2-chronicles-36-he-sent-his-messengers-but-they-mocked-till-there-was-no-remedy'
ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;

